:host{font-family:"Bricolage Grotesque Variable",sans-serif;--paper:#f7f6f2;--surface:#fffefd;--ink:#242323;--muted:#615d5a;--rule:#d4cfcb;--accent:#b3342a;--button:#b3342a;--tint:#f3e9e5;--ease-out:cubic-bezier(.23,1,.32,1);color:var(--ink)}*{box-sizing:border-box}[hidden]{display:none!important}p,h3,ul{margin:0}p{line-height:1.7}button,input,textarea{font:inherit}button{cursor:pointer}:focus-visible{outline:3px solid var(--accent);outline-offset:5px}
.button { display: inline-flex; align-items: center; justify-content: center; gap: 20px; min-height: 54px; padding: 16px 22px; border: 1px solid var(--button); border-radius: 3px; color: #fff; background: var(--button); font-size: 14px; font-weight: 700; line-height: 1.3; text-decoration: none; transition: transform 140ms var(--ease-out), background-color 160ms ease; }
.button:active { transform: scale(.98); }
.button-ink { --button: #242323; }

@media (hover: hover) and (pointer: fine) {
  .button:hover { background: #91281f; border-color: #91281f; }
  .button-ink:hover { background: #161515; border-color: #161515; }
}
.button-ink { --button: #242323; }

