.recall-experiment { color: #242323; --ink: #242323; --muted: #615d5a; --paper: #f7eeeb; --accent: #b3342a; margin-top: 24px; padding: 24px 28px; background: #f7eeeb; }
.recall-instruction { font-size: 14px; line-height: 1.6; min-height: 45px; font-weight: 500; }
.recall-stage { min-height: 180px; display: flex; align-items: center; padding-block: 20px; }
.recall-words { display: grid; gap: 5px; font-size: clamp(30px, 3vw, 40px); line-height: 1.16; font-weight: 550; letter-spacing: -.02em; }
.recall-question { font-size: 36px; line-height: 1.15; letter-spacing: -.025em; }
.recall-controls { display: flex; flex-wrap: wrap; gap: 12px 18px; align-items: center; }
.button-ink { --button: #242323; }
.recall-controls .button { font-size: 13px; gap: 14px; padding-inline: 17px; }
.recall-reset { color: #242323; background: transparent; border: 0; min-height: 44px; padding: 10px 0; font-size: 14px; text-decoration: underline; text-underline-offset: 4px; }
.recall-explanation { margin-top: 23px; padding-top: 18px; border-top: 1px solid #cdb7b0; font-size: 16px; }
.recall-explanation strong { display: block; font-weight: 600; margin-bottom: 8px; }
.recall-experiment :focus-visible { outline-color: #b3342a; }
@media (max-width: 1100px) and (min-width: 768px) {
  .recall-experiment { padding-inline: 22px; }
}
@media (max-width: 767px) {
  .recall-experiment { padding: 22px 24px; margin-top: 20px; }
  .recall-instruction { font-size: 14px; }
  .recall-stage { min-height: 180px; }
  .recall-words { font-size: 35px; }
  .recall-question { font-size: 33px; }
  .recall-controls .button { font-size: 13px; padding-inline: 15px; gap: 12px; }
}
@media (max-width: 359px) {
  .recall-experiment { padding-inline: 20px; }
  .recall-words { font-size: 30px; }
  .recall-controls .button { font-size: 12px; }
}

:host{font-family:"Bricolage Grotesque Variable",sans-serif;--paper:#f7f6f2;--surface:#fffefd;--ink:#242323;--muted:#615d5a;--rule:#d4cfcb;--accent:#b3342a;--button:#b3342a;--tint:#f3e9e5;--ease-out:cubic-bezier(.23,1,.32,1);color:var(--ink)}*{box-sizing:border-box}[hidden]{display:none!important}p,h3,ul{margin:0}p{line-height:1.7}button,input,textarea{font:inherit}button{cursor:pointer}:focus-visible{outline:3px solid var(--accent);outline-offset:5px}

.workshop-section { background: #252221; color: #f8f4f0; --paper: #252221; --surface: #302b29; --ink: #f8f4f0; --muted: #d3c9c1; --rule: #5b504b; --accent: #f18c7e; --tint: #352c29; }
.workshop summary { display: flex; justify-content: space-between; gap: 20px; align-items: center; padding: 23px 0; cursor: pointer; list-style: none; }
.workshop summary > .ph { font-size: 24px; }
.workshop-name { display: flex; flex-direction: column; gap: 9px; font-size: clamp(26px, 2.7vw, 36px); line-height: 1.16; letter-spacing: -.025em; font-weight: 600; }
.workshop-name > span { font-size: 13px; color: var(--muted); letter-spacing: 0; font-weight: 450; }
.workshop[open] > summary { color: var(--accent); }
.workshop[open] > summary > .ph-plus { transform: rotate(45deg); }
.workshop-content { font-size: 16px; padding-bottom: 26px; }
.workshop-content > p { color: var(--muted); max-width: 48ch; margin-bottom: 18px; }
.workshop-content ul { font-size: 16px; }
.workshop-section :focus-visible { outline-color: #f18c7e; }

@media (hover: hover) and (pointer: fine) {
  .workshop > summary:hover { color: var(--accent); }
}
@media (max-width: 767px) {
  .workshop summary { padding-block: 22px; }
  .workshop-name { font-size: 28px; }
  .workshop-name > span { font-size: 13px; }
  .workshop-content { padding-bottom: 24px; }
}
